const incoming = $json.body ?? $json;

const status = String(
  incoming.status ?? "unknown"
).trim().toLowerCase();

const missionId = String(
  incoming.mission_id ?? "unknown"
);

const completed = status === "completed";

const detectedLabels = Array.isArray(
  incoming.detected_labels
)
  ? incoming.detected_labels
  : [];

const capturePath =
  incoming.capture_path ?? null;

const errorMessage =
  incoming.error ?? null;

const resultLabel = completed
  ? "SUCCESS"
  : "FAILURE";

const reportLines = [
  "RoboOps AI Mission Report",
  "=========================",
  `Result: ${resultLabel}`,
  `Mission ID: ${missionId}`,
  `Plan ID: ${incoming.plan_id ?? "N/A"}`,
  `Status: ${status}`,
  `Action: ${incoming.action ?? "N/A"}`,
  `Target: ${incoming.target ?? "N/A"}`,
  `Progress: ${incoming.progress_percent ?? 0}%`,
  `Current step: ${incoming.current_step ?? "N/A"}`,
  `Total steps: ${incoming.total_steps ?? 0}`,
  `Detection count: ${incoming.detection_count ?? 0}`,
  `Detected labels: ${
    detectedLabels.length
      ? detectedLabels.join(", ")
      : "None"
  }`,
  `Capture: ${capturePath ?? "None"}`,
  `Error: ${errorMessage ?? "None"}`,
  `Robot event time: ${incoming.event_at ?? "N/A"}`,
  `Automation time: ${new Date().toISOString()}`,
];

return [
  {
    json: {
      ...incoming,
      status,
      mission_id: missionId,
      result: resultLabel,
      completed,
      report_subject:
        `RoboOps mission ${status}: ${missionId}`,
      report_text: reportLines.join("\n"),
      automation_received_at:
        new Date().toISOString(),
    },
  },
];

return items.map((item) => {
  return {
    json: {
      acknowledged: true,
      automation_branch: "completed",
      result: "SUCCESS",
      mission_id: item.json.mission_id,
      status: item.json.status,
      report_subject:
        item.json.report_subject,
      report_text:
        item.json.report_text,
      capture_path:
        item.json.capture_path ?? null,
      processed_at:
        new Date().toISOString(),
    },
  };
});

return items.map((item) => {
  return {
    json: {
      acknowledged: true,
      automation_branch: "failed",
      result: "FAILURE",
      mission_id: item.json.mission_id,
      status: item.json.status,
      error:
        item.json.error ??
        "Mission failed without an error message",
      report_subject:
        item.json.report_subject,
      report_text:
        item.json.report_text,
      processed_at:
        new Date().toISOString(),
    },
  };
});
